"""Apply refs/bib_corrections.csv to refs/references.bib (generated by tools/fetch_bibtex.py),
and set the year in refs/verification.csv to the corrected bib year, so that
`fetch_bibtex.py --check` (which compares the two years) stays consistent.

Each correction is documented with its evidence in the CSV (citation workstream C, D-131).
`make refs` regenerates references.bib from the registries and drops these corrections, so
re-run this script after it until tools/fetch_bibtex.py applies the table itself.
"""
import csv
import re
import sys
from pathlib import Path

ROOT = Path(sys.argv[1])
BIB = ROOT / "refs" / "references.bib"
VER = ROOT / "refs" / "verification.csv"
COR = ROOT / "refs" / "bib_corrections.csv"

raw = BIB.read_bytes().decode("utf-8")
crlf = "\r\n" in raw
text = raw.replace("\r\n", "\n")
chunks = re.split(r"(\n\s*\n)", text)


def find(key):
    for i, c in enumerate(chunks):
        if re.search(r"@\w+\s*\{\s*" + re.escape(key) + r"\s*,", c):
            return i
    raise KeyError(key)


with COR.open(encoding="utf-8", newline="") as f:
    rows = list(csv.DictReader(f))
done = []
for r in rows:
    i = find(r["key"])
    c = chunks[i]
    if r["action"] == "replace":
        if r["new"] in c:
            continue  # already applied (the new text may contain the old one)
        n = c.count(r["old"])
        if n != 1:
            sys.exit(f"{r['key']}: expected one occurrence of {r['old']!r}, found {n}")
        chunks[i] = c.replace(r["old"], r["new"])
    elif r["action"] == "add":
        if r["new"] in c:
            continue
        m = re.search(r"@\w+\s*\{\s*" + re.escape(r["key"]) + r"\s*,", c)
        chunks[i] = c[: m.end()] + " " + r["new"] + "," + c[m.end():]
    else:
        sys.exit(f"unknown action {r['action']}")
    done.append(r["key"])

out = "".join(chunks)
BIB.write_bytes((out.replace("\n", "\r\n") if crlf else out).encode("utf-8"))

# keep verification.csv years equal to the corrected bib years
years = {}
for k in {r["key"] for r in rows}:
    c = chunks[find(k)]
    m = re.search(r"\byear\s*=\s*\{?(\d{4})", c)
    if m:
        years[k] = m.group(1)
with VER.open(encoding="utf-8", newline="") as f:
    reader = csv.DictReader(f)
    fields = reader.fieldnames
    vrows = list(reader)
changed = []
for v in vrows:
    if v["key"] in years and v["year"] != years[v["key"]]:
        changed.append((v["key"], v["year"], years[v["key"]]))
        v["year"] = years[v["key"]]
with VER.open("w", encoding="utf-8", newline="") as f:
    w = csv.DictWriter(f, fieldnames=fields)
    w.writeheader()
    w.writerows(vrows)
print("applied:", done)
print("verification years:", changed)
